/// <summary>
/// Extension of WrkCtrActivityResourceRequirement
/// </summary>
[ExtensionOf(tableStr(WrkCtrActivityResourceRequirement))]
final public class AVAWrkCtrActivityResourceRequirementDbt_Extension
{
}

Method.Source:
/// <summary>
/// Display WrkCtrId
/// </summary>
/// <returns>WrkCtrId</returns>
public display WrkCtrId avaDisplayWrkCtrId()
{
    return this.WrkCtrId;
}

/// <summary>
/// Gets and sets the resource based on <c>WrkCtrId</c>.
/// </summary>
/// <param name="_set">
/// true if the resource ID is set; otherwise, false.
/// </param>
/// <param name="_wrkCtrActivityRequirementEdit">
/// The new resource ID value when <paramref name="set"/> is true.
/// </param>
/// <param name="_wrkCtrActivityRequirement">
/// The parent activity requirement record.
/// </param>
/// <param name="_allowBlank">
/// A <c>Boolean</c> specifying if the method accepts a blank string as input.
/// </param>
/// <param name="_companyId">The company ID.</param>
/// <returns>
/// A string with the ID of the resource.
/// </returns>
/// <exception cref="Exception::Warning">
/// The value in field requirement is not found in relating table Resources.
/// </exception>
public WrkCtrActivityRequirementEdit requirementEdit(
    boolean                                 _set,
    WrkCtrActivityRequirementEdit           _wrkCtrActivityRequirementEdit,
    WrkCtrActivityRequirement               _wrkCtrActivityRequirement,
    boolean                                 _allowBlank,
    CompanyId                               _companyId
    )
{
    CompanyId                       avaCompanyId = _companyId;
    WrkCtrTable                     avaWrkCtrTable;
    WrkCtrActivityRequirementEdit   avaWrkCtrActivityRequirementEdit;

    if(avaCompanyId == '')
    {
        avaCompanyId = _wrkCtrActivityRequirement.getCompanyContext(true);
    }

    avaWrkCtrActivityRequirementEdit = next requirementEdit(_set, _wrkCtrActivityRequirementEdit, _wrkCtrActivityRequirement, _allowBlank, avaCompanyId);

    if (_set)
    {
        // Change the company to make sure the find is done in the same company as the activity
        changecompany(avaCompanyId)
        {
            avaWrkCtrTable = WrkCtrTable::find(_wrkCtrActivityRequirementEdit);

            if (avaWrkCtrTable.RecId && avaWrkCtrTable.KCS_NotActiveWrkCtr)
            {
                throw warning(strFmt("@NDX:NXAResourceInactiveError", avaWrkCtrTable.WrkCtrId));
            }
        }
    }

    return avaWrkCtrActivityRequirementEdit;
}
